def sanitize_content(content, filepath):
    if filepath.endswith(('.kt', '.kts')):
        import re
        def replacer(match):
            return ''.join('\n' if char == '\n' else ' ' for char in match.group(0))
        content = re.sub(r'"""[\s\S]*?"""', replacer, content)

        result = []
        i = 0
        n = len(content)
        state = 'NORMAL'
        while i < n:
            c = content[i]
            if state == 'NORMAL':
                if c == '/' and i + 1 < n and content[i+1] == '/':
                    state = 'LINE_COMMENT'
                    result.append('  ')
                    i += 2
                elif c == '/' and i + 1 < n and content[i+1] == '*':
                    state = 'BLOCK_COMMENT'
                    result.append('  ')
                    i += 2
                elif c == '"':
                    state = 'STRING_DOUBLE'
                    result.append(' ')
                    i += 1
                elif c == "'":
                    state = 'STRING_SINGLE'
                    result.append(' ')
                    i += 1
                else:
                    result.append(c)
                    i += 1
            elif state == 'LINE_COMMENT':
                if c == '\n':
                    state = 'NORMAL'
                    result.append('\n')
                else:
                    result.append(' ')
                i += 1
            elif state == 'BLOCK_COMMENT':
                if c == '*' and i + 1 < n and content[i+1] == '/':
                    state = 'NORMAL'
                    result.append('  ')
                    i += 2
                else:
                    if c == '\n': result.append('\n')
                    else: result.append(' ')
                    i += 1
            elif state == 'STRING_DOUBLE':
                if c == '\\' and i + 1 < n:
                    result.append('  ')
                    i += 2
                elif c == '"':
                    state = 'NORMAL'
                    result.append(' ')
                    i += 1
                else:
                    if c == '\n': result.append('\n')
                    else: result.append(' ')
                    i += 1
            elif state == 'STRING_SINGLE':
                if c == '\\' and i + 1 < n:
                    result.append('  ')
                    i += 2
                elif c == "'":
                    state = 'NORMAL'
                    result.append(' ')
                    i += 1
                else:
                    if c == '\n': result.append('\n')
                    else: result.append(' ')
                    i += 1
        return "".join(result)

    elif filepath.endswith(('.js', '.ts', '.jsx', '.tsx')):
        result = []
        i = 0
        n = len(content)
        state = 'NORMAL'
        template_brace_levels = []
        current_brace_level = 0

        def expects_regex():
            j = i - 1
            while j >= 0:
                c = content[j]
                if c.isspace():
                    j -= 1
                    continue
                if c in '$_' or c.isalnum():
                    end = j + 1
                    while j >= 0 and (content[j].isalnum() or content[j] in '$_'):
                        j -= 1
                    word = content[j+1:end]
                    if word in {'return', 'yield', 'await', 'typeof', 'instanceof', 'case', 'throw', 'delete', 'void', 'do', 'else', 'in', 'of', 'new', 'if', 'while', 'for', 'with'}:
                        return True
                    return False
                if c in ')]}':
                    return False
                if c in '"\'`': 
                    return False
                if c == '<' and j == i - 1:
                    return False
                return True
            return True

        while i < n:
            c = content[i]

            if state == 'NORMAL':
                if c == '{':
                    current_brace_level += 1
                    result.append(c)
                    i += 1
                elif c == '}':
                    current_brace_level -= 1
                    result.append(c)
                    i += 1
                    if template_brace_levels and current_brace_level == template_brace_levels[-1]:
                        template_brace_levels.pop()
                        state = 'TEMPLATE'
                elif c == '/' and i + 1 < n and content[i+1] == '/':
                    state = 'LINE_COMMENT'
                    result.append('  ')
                    i += 2
                elif c == '/' and i + 1 < n and content[i+1] == '*':
                    state = 'BLOCK_COMMENT'
                    result.append('  ')
                    i += 2
                elif c == "'":
                    state = 'STRING_SINGLE'
                    result.append(' ')
                    i += 1
                elif c == '"':
                    state = 'STRING_DOUBLE'
                    result.append(' ')
                    i += 1
                elif c == '`':
                    state = 'TEMPLATE'
                    result.append(' ')
                    i += 1
                elif c == '/':
                    if expects_regex():
                        state = 'REGEX'
                        result.append(' ')
                        i += 1
                    else:
                        result.append(c)
                        i += 1
                else:
                    result.append(c)
                    i += 1

            elif state == 'LINE_COMMENT':
                if c == '\n':
                    state = 'NORMAL'
                    result.append('\n')
                else:
                    result.append(' ')
                i += 1

            elif state == 'BLOCK_COMMENT':
                if c == '*' and i + 1 < n and content[i+1] == '/':
                    state = 'NORMAL'
                    result.append('  ')
                    i += 2
                else:
                    if c == '\n': result.append('\n')
                    else: result.append(' ')
                    i += 1

            elif state == 'STRING_SINGLE':
                if c == '\\' and i + 1 < n:
                    result.append('  ')
                    i += 2
                elif c == "'":
                    state = 'NORMAL'
                    result.append(' ')
                    i += 1
                else:
                    if c == '\n': result.append('\n')
                    else: result.append(' ')
                    i += 1

            elif state == 'STRING_DOUBLE':
                if c == '\\' and i + 1 < n:
                    result.append('  ')
                    i += 2
                elif c == '"':
                    state = 'NORMAL'
                    result.append(' ')
                    i += 1
                else:
                    if c == '\n': result.append('\n')
                    else: result.append(' ')
                    i += 1

            elif state == 'TEMPLATE':
                if c == '\\' and i + 1 < n:
                    result.append('  ')
                    i += 2
                elif c == '$' and i + 1 < n and content[i+1] == '{':
                    template_brace_levels.append(current_brace_level)
                    current_brace_level += 1
                    state = 'NORMAL'
                    result.append(' {')
                    i += 2
                elif c == '`':
                    state = 'NORMAL'
                    result.append(' ')
                    i += 1
                else:
                    if c == '\n': result.append('\n')
                    else: result.append(' ')
                    i += 1

            elif state == 'REGEX':
                if c == '\\' and i + 1 < n:
                    result.append('  ')
                    i += 2
                elif c == '/':
                    state = 'NORMAL'
                    result.append(' ')
                    i += 1
                elif c == '[':
                    state = 'REGEX_CLASS'
                    result.append(' ')
                    i += 1
                else:
                    if c == '\n': 
                        state = 'NORMAL'
                        result.append('\n')
                    else: result.append(' ')
                    i += 1

            elif state == 'REGEX_CLASS':
                if c == '\\' and i + 1 < n:
                    result.append('  ')
                    i += 2
                elif c == ']':
                    state = 'REGEX'
                    result.append(' ')
                    i += 1
                else:
                    if c == '\n':
                        state = 'NORMAL'
                        result.append('\n')
                    else:
                        result.append(' ')
                    i += 1
        return "".join(result)

    else:
        result = []
        i = 0
        n = len(content)
        state = 'NORMAL'
        while i < n:
            c = content[i]
            if state == 'NORMAL':
                if c == '/' and i + 1 < n and content[i+1] == '/':
