            elif state == 'LINE_COMMENT':
                if c == '\n':
                    state = 'NORMAL'
                    result.append('\n')
                else:
                    result.append(' ')
                i += 1
            elif state == 'BLOCK_COMMENT':
                if c == '*' and i + 1 < n and content[i+1] == '/':
                    state = 'NORMAL'
                    result.append('  ')
                    i += 2
                else:
                    if c == '\n': result.append('\n')
                    else: result.append(' ')
                    i += 1
            elif state == 'STRING_DOUBLE':
                if c == '\\' and i + 1 < n:
                    result.append('  ')
